import {characterArt,characterNames,fallbackHaunt} from './haunt-art.js';

const $=s=>document.querySelector(s);
const API='/api/memory-chat';
const SEEN_KEY='memory-glitch-seen-haunts-v4';
const CHAOS_KEY='memory-glitch-chaos-mode';
let chaosEnabled=true;
try{chaosEnabled=localStorage.getItem(CHAOS_KEY)!=='off'}catch{}
const CAT_IMAGES=Object.freeze({chaos:{url:'./assets/cat-chaos.jpg',alt:'An orange cat making an unhinged face'},calico:{url:'./assets/cat-calico.jpg',alt:'A calico cat with oversized glasses and buck teeth'},polite:{url:'./assets/cat-polite.jpg',alt:'An awkwardly polite smiling white cat'},dinner:{url:'./assets/cat-dinner.jpg',alt:'Woman yelling beside a confused cat at a dinner table'},grumpy:{url:'./assets/cat-grumpy.jpg',alt:'A grumpy-looking cat'},crying:{url:'./assets/cat-crying.png',alt:'A cat with edited teary eyes'},confused:{url:'./assets/cat-confused.jpg',alt:'A confused-looking cat'},surprised:{url:'./assets/cat-surprised.jpg',alt:'A surprised-looking cat'},'trump-1':{url:'./assets/trump-meme-1.gif',alt:'Animated Trump caricature dancing',source:'https://tenor.com/view/trump-dancing-dance-move-gif-16005737',memeTemplate:true},'trump-2':{url:'./assets/trump-meme-2.gif',alt:'Donald Trump winking with an existing humorous caption',source:'https://tenor.com/view/donald-trump-wink-president-usa-gif-2973401692064150166',memeTemplate:true},'trump-3':{url:'./assets/trump-meme-3.gif',alt:'Donald Trump pointing and giving a thumbs up with an existing I see what you did there caption',source:'https://tenor.com/view/i-see-you-i-see-what-you-did-there-trump-wink-thumbs-up-gif-11497468735575552050',memeTemplate:true},'trump-4':{url:'./assets/trump-meme-4.gif',alt:'Donald Trump laughing at a podium',source:'https://tenor.com/pt-BR/view/trump-laughing-gif-6044302',memeTemplate:true},'trump-5':{url:'./assets/trump-meme-5.gif',alt:'Donald Trump making a wrong reaction at a debate microphone',source:'https://tenor.com/view/wrong-drumpf-trump-stupid-gif-6220235',memeTemplate:true}});
function catFor(message){const candidate=message.haunt?.catId||message.reaction?.catId;if(typeof candidate==='string'&&Object.hasOwn(CAT_IMAGES,candidate))return {id:candidate,...CAT_IMAGES[candidate]};const hash=[...String(message.id||message.text||'')].reduce((a,c)=>(a*31+c.charCodeAt(0))>>>0,0);const ids=Object.keys(CAT_IMAGES),id=ids[hash%ids.length];return {id,...CAT_IMAGES[id]}}
function catImage(cat,className=''){const image=el('img',className);image.src=cat.url;image.alt=cat.alt;image.decoding='async';return image}

let state={version:3,revision:0,chat:[],sources:[],lastAudit:null},configured=false,busy=false,pending=false,demoResult=null,toastTimer;
const seenIncidents=new Set();
try{const saved=JSON.parse(sessionStorage.getItem(SEEN_KEY)||'[]');if(Array.isArray(saved))saved.filter(v=>typeof v==='string').forEach(id=>seenIncidents.add(id))}catch{}
const el=(tag,className,text)=>{const n=document.createElement(tag);if(className)n.className=className;if(text!==undefined)n.textContent=text;return n};
const button=(text,className,handler)=>{const n=el('button',className,text);n.type='button';n.addEventListener('click',handler);return n};
const formatTime=value=>{const date=new Date(value);return Number.isNaN(+date)?'':date.toLocaleString('en-AU',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false})};
const safeUrl=value=>{try{const u=new URL(value);return u.protocol==='https:'?u.href:null}catch{return null}};
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),6500)}
function showDialog(id){const dialog=$(id);if(!dialog.open)dialog.showModal()}
function setBusy(value,text='Replying and checking the paper trail…'){busy=value;$('#send').disabled=value||!configured;$('#demo-run').disabled=value||!configured;$('#demo-case').disabled=value;$('#chaos-toggle').disabled=value;$('#compose-status').textContent=value?text:'Enter to send · Shift + Enter for a new line';document.querySelectorAll('[data-mutation]').forEach(n=>n.disabled=value||n.dataset.completed==='true');$('#message').setAttribute('aria-busy',String(value))}
async function api(operation,data={}){
 const response=await fetch(API,{method:operation?'POST':'GET',credentials:'same-origin',headers:operation?{'Content-Type':'application/json'}:undefined,body:operation?JSON.stringify({operation,revision:state.revision,...data}):undefined});
 let payload;try{payload=await response.json()}catch{throw new Error('The server returned an unreadable response. Please try again. Your draft is still here.')}
 if(!response.ok){if(response.status===409){await load();throw new Error('This session changed in another tab. The latest records are loaded; please send your draft again.')}throw new Error(payload.error||payload.message||'The request failed. Please try again.')}
 if(payload.state)state=payload.state;
 if(typeof payload.configured==='boolean')configured=payload.configured;
 return payload;
}
function updateChaosControl(){const toggle=$('#chaos-toggle'),count=Number.isInteger(state.chaosCounter)&&state.chaosCounter>=0&&state.chaosCounter<=2?state.chaosCounter:0;toggle.setAttribute('aria-pressed',String(chaosEnabled));toggle.classList.toggle('active',chaosEnabled);toggle.querySelector('.chaos-state').textContent=chaosEnabled?'ON':'OFF';toggle.querySelector('.chaos-progress').textContent=`${count}/3`;toggle.title=chaosEnabled?`Two normal replies, then one playful burst. Next burst in ${3-count} ${3-count===1?'reply':'replies'}. Evidence-backed memory alerts remain immediate.`:'Chaos off: plain replies. Evidence-backed memory alerts remain immediate.';toggle.setAttribute('aria-label',chaosEnabled?`Chaos on, every third reply. ${count} of 3 replies counted. Toggle off.`:'Chaos off. Toggle on for a playful burst every third reply.');const intro=$('#chaos-intro');if(intro)intro.textContent=chaosEnabled?'Two normal replies. One chaotic detour. Repeat.':'Plain answers. Real memory alerts still get receipts.'}

function rememberIncident(key){if(!key)return;seenIncidents.add(key);try{sessionStorage.setItem(SEEN_KEY,JSON.stringify([...seenIncidents].slice(-250)))}catch{}}
function incidentKey(message,isDemo=false){return `${isDemo?'demo:':'chat:'}${message.id||message.time||message.text?.slice(0,100)||'incident'}`}
function hauntFor(message){const fallback=fallbackHaunt(message.id||message.text);const h=message.haunt;if(!h||typeof h!=='object')return fallback;return {character:Object.hasOwn(characterNames,h.character)?h.character:fallback.character,line:typeof h.line==='string'&&h.line.trim()?h.line:fallback.line,admission:typeof h.admission==='string'&&h.admission.trim()?h.admission:fallback.admission}}
function celebrateIncident(message,isDemo=false){
 if(message.check?.status!=='issue'||!message.check.issues?.length)return;
 const key=incidentKey(message,isDemo);if(seenIncidents.has(key))return;rememberIncident(key);
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const layer=$('#haunt-effects');if(!layer||layer.childElementCount)return;
 const haunt=hauntFor(message);const types=haunt.character==='trump'?['trump','candy','spider','pumpkin']:[haunt.character,'candy',haunt.character,'ghost'];
 const selected=catFor(message),pool=Object.values(CAT_IMAGES).filter(cat=>cat.url!==selected.url),extras=[];for(let i=0;i<2&&pool.length;i++)extras.push(pool.splice(Math.floor(Math.random()*pool.length),1)[0]);[selected,...extras].forEach((cat,index)=>{const particle=el('span','haunt-particle cat-particle');particle.style.left=`${12+index*29}%`;particle.style.animationDelay=`${index*.15}s`;particle.append(catImage(cat));layer.append(particle);particle.addEventListener('animationend',()=>particle.remove(),{once:true});setTimeout(()=>particle.remove(),4000)});
 types.forEach((type,index)=>{const particle=el('span',`haunt-particle ${type}`);particle.style.left=`${7+index*25+Math.random()*7}%`;particle.style.animationDelay=`${index*.17}s`;particle.append(characterArt(type));layer.append(particle);particle.addEventListener('animationend',()=>particle.remove(),{once:true});setTimeout(()=>particle.remove(),4000)});
}
function normalReaction(message){const value=message.reaction;if(message.check?.status==='issue'&&message.check.issues?.length)return null;return value&&typeof value.caption==='string'&&value.caption.trim()?{cat:catFor(message),caption:value.caption.slice(0,160)}:null}
function celebrateReaction(message){
 if(!chaosEnabled||!normalReaction(message))return;
 const key=`reaction:${incidentKey(message)}`;if(seenIncidents.has(key))return;rememberIncident(key);
 if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const layer=$('#haunt-effects');if(!layer||layer.childElementCount)return;
 const selected=catFor(message),pool=Object.values(CAT_IMAGES).filter(cat=>cat.url!==selected.url);
 [selected,pool[Math.floor(Math.random()*pool.length)]].forEach((cat,index)=>{const particle=el('span','haunt-particle cat-particle reaction-particle');particle.style.left=`${index?73:9}%`;particle.style.animationDelay=`${index*.12}s`;particle.append(catImage(cat));layer.append(particle);particle.addEventListener('animationend',()=>particle.remove(),{once:true});setTimeout(()=>particle.remove(),2500)});
}
function reactionCard(message){
 const reaction=normalReaction(message);if(!reaction)return null;
 const card=el('section','chat-reaction');card.setAttribute('aria-label','Entertainment meme reaction, not a memory alert');card.dataset.catId=reaction.cat.id;
 card.append(el('p','reaction-label','CHAT REACTION / NOT A MEMORY ALERT'));
 const frame=el('figure','reaction-meme'),caption=el('figcaption');caption.append(el('h3','',reaction.caption));const image=catImage(reaction.cat);image.addEventListener('error',()=>image.hidden=true,{once:true});frame.append(image,caption);card.append(frame);
 const credit=el('a','reaction-credit',reaction.cat.memeTemplate?'Parody caption · Reaction GIF source ↗':'Fictional comedy · Image source ↗');credit.href=reaction.cat.source||'./assets/cat-sources.json';credit.target='_blank';credit.rel='noopener noreferrer';card.append(credit);return card;
}
async function load(){try{const payload=await api();$('#connection').className=`connection ${configured?'connected':'error'}`;$('#connection').replaceChildren(el('i'),document.createTextNode(configured?'Netlify connected':'AI not configured'));$('#connection').title=payload.model?`Chat model: ${payload.model}`:'Netlify Functions + Blobs';for(const message of state.chat||[]){if(message.check?.status==='issue')rememberIncident(incidentKey(message));if(message.reaction)rememberIncident(`reaction:${incidentKey(message)}`)}render();setBusy(false)}catch(error){$('#connection').className='connection error';$('#connection').replaceChildren(el('i'),document.createTextNode('Connection unavailable'));toast(error.message);render();setBusy(false)}}
function findSource(id){return(state.sources||[]).find(source=>source.id===id)}
function openSources(id,quote){$('#source-dialog-title').textContent=id?'The cited original message':'All original messages';const wrap=$('#source-detail');wrap.replaceChildren();const found=id?findSource(id):null;const list=id?(found?[found]:quote?[{id,text:quote}]:[]):[...(state.sources||[])].reverse();if(!list.length)wrap.append(el('p','dialog-note','No originals yet. Your messages are saved automatically in this session.'));for(const source of list){const card=el('article','source-detail-card');card.append(el('small','',`${source.id||'Original'}${source.time?' · '+formatTime(source.time):''}`),el('p','',source.text));wrap.append(card)}showDialog('#source-dialog')}
function openAudit(){$('#audit-detail').textContent=state.lastAudit?JSON.stringify(state.lastAudit,null,2):'No server receipt yet. Send a message to begin.';showDialog('#audit-dialog')}
function checkLine(check){if(!check)return null;const coverage=check.referenceCoverage;const coverageText=coverage&&coverage.complete===false?`${coverage.checked}/${coverage.total}`:String(check.checkedSources??coverage?.checked??0);const line=el('div',`check-line ${check.status||''}`);let text;if(check.status==='issue')text=`${check.issues?.length||1} evidence-backed mismatch found. Check the receipts below.`;else if(check.status==='clear')text=`Checked ${coverageText} original messages. No supported mismatch found; this is not a full fact-check.`;else if(check.status==='uncertain')text='Not enough evidence to decide. No memory alert.';else text='The independent check did not complete. Please review this reply yourself.';if(coverage?.complete===false&&check.status!=='clear')text+=` · Reference coverage: ${coverage.checked}/${coverage.total}.`;line.append(el('span','check-icon',check.status==='clear'?'✓':check.status==='issue'?'⌁':'○'),el('span','',text));return line}
function hauntCard(message){const haunt=hauntFor(message),cat=catFor(message);const card=el('section',`haunt-card cat-haunt ${haunt.character}`);card.dataset.hauntCharacter=haunt.character;card.dataset.catId=cat.id;card.setAttribute('aria-label','An image meme with a memory correction');card.append(el('p','haunt-character',characterNames[haunt.character]));const frame=el('figure','cat-meme-frame');const caption=el('figcaption','cat-meme-caption');caption.append(el('h3','haunt-line',haunt.line));const photoWrap=el('div','cat-meme-photo');const img=catImage(cat);const fallback=el('p','cat-photo-fallback','The meme image could not load. The caption and correction are still here.');fallback.hidden=true;img.addEventListener('error',()=>{img.hidden=true;fallback.hidden=false},{once:true});photoWrap.append(img,fallback);frame.append(caption,photoWrap);const sticker=el('span','cat-character-sticker');sticker.append(characterArt(haunt.character));frame.append(sticker);card.append(frame);const credit=el('a','cat-image-credit',cat.memeTemplate?'Reaction GIF · Fictional caption · Source ↗':'Meme image · Fictional caption · Source ↗');credit.href=cat.source||'./assets/cat-sources.json';credit.target='_blank';credit.rel='noopener noreferrer';card.append(credit);const admission=el('p','haunt-admission');admission.append(el('strong','','Translation: '),document.createTextNode(haunt.admission));card.append(admission);return card}
function issueBlock(issue){const block=el('section','issue-block');block.append(el('div','issue-heading',issue.kind==='missing'?'⌁ The record had the answer. The reply missed it.':'⌁ A reply contradicted your earlier message.'));const content=el('div','issue-evidence');const pair=el('div','evidence-pair');for(const[label,value]of[['YOU SAID',issue.sourceQuote],['AI REPLIED',issue.replyQuote]]){const item=el('div');item.append(el('label','',label),el('p','',value||'No quote supplied'));pair.append(item)}const correction=el('p','correction');correction.append(el('strong','','THE CORRECTION'),document.createTextNode(issue.correction||issue.explanation||'Please compare the reply with the original message.'));const foot=el('div','evidence-foot');foot.append(el('span','',issue.inContext===true?'The chat model received this original, but still mismatched it.':issue.inContext===false?'This original was outside the current chat context.':'Context inclusion has not been confirmed.'),button('View original ↗','',()=>openSources(issue.sourceId,issue.sourceQuote)));content.append(pair,correction,foot);block.append(content);return block}
function memeCard(meme,message,isDemo=false){const card=el('section','meme-card');const tag=el('div','meme-tag','THE MEME AFTERPARTY');tag.append(el('span','','AI captions · Fictional comedy'));card.append(tag);const title=el('div','template-heading');title.append(el('h3','',meme.title||'A small memory malfunction'),el('p','',meme.caption||''));card.append(title);const template=meme.template,url=safeUrl(template?.url);
 if(url){const visual=el('div',`meme-template ${template.layout==='drake'?'layout-drake':'layout-classic'}`);const img=el('img');img.alt=`${template.name||'Internet meme'} template`;img.referrerPolicy='no-referrer';img.loading='lazy';img.decoding='async';img.src=url;visual.append(img,el('div','meme-overlay overlay-top',meme.topText||''),el('div','meme-overlay overlay-bottom',meme.bottomText||meme.caption||''));const fallback=el('div','template-fallback');fallback.hidden=true;fallback.append(el('p','','The template image could not load. Here are the generated captions.'),el('strong','',meme.topText||''),el('strong','',meme.bottomText||meme.caption||''));img.addEventListener('error',()=>{visual.hidden=true;fallback.hidden=false});card.append(visual,fallback)}else{const fallback=el('div','template-fallback');fallback.append(el('p','','No image template was available. The joke is still here.'),el('strong','',meme.topText||''),el('strong','',meme.bottomText||meme.caption||''));card.append(fallback)}
 const bottom=el('div','meme-bottom'),attribution=el('span','','Fictional comedy. Never saved as a fact.');const sourceUrl=safeUrl(template?.sourceUrl);if(sourceUrl){const link=el('a','template-credit',`${template.name||'Imgflip'} ↗`);link.href=sourceUrl;link.target='_blank';link.rel='noopener noreferrer';attribution.replaceChildren(link,el('span','',' · AI captions'))}bottom.append(attribution);
 if(!isDemo){const feedback=el('div','meme-feedback');feedback.append(el('span','','Did it land?'));for(const[label,value]of[['Made me laugh',true],['Not quite',false]]){const selected=message.feedback===value||message.feedback?.funny===value;const b=button(label,selected?'chosen':'',()=>mutate('feedback',{messageId:message.id,funny:value}));b.dataset.mutation='true';b.disabled=busy;feedback.append(b)}bottom.append(feedback)}else bottom.append(el('span','','Demo only · Not saved to your chat'));card.append(bottom);if(meme.story){const details=el('details','meme-story');details.append(el('summary','','Read the whole joke'),el('p','',meme.story));card.append(details)}return card}
function messageNode(message,isDemo=false){const item=el('article',`message ${message.role==='user'?'user':'assistant'}`);if(message.id)item.dataset.messageId=message.id;const meta=el('div','message-meta');meta.append(el('span','avatar',message.role==='user'?'Y':'✳'),el('span','',message.role==='user'?'YOU':isDemo?'AI · SCRIPTED REPLY':'MEMORY GLITCH'));if(message.time)meta.append(el('span','',formatTime(message.time)));item.append(meta,el('div','message-text',message.text||''));if(message.role!=='user'){const check=message.check;if(check){const line=checkLine(check);if(line)item.append(line);if(check.status==='issue'&&check.issues?.length){item.append(hauntCard(message));for(const issue of check.issues)item.append(issueBlock(issue))}}if(!isDemo){const reaction=reactionCard(message);if(reaction)item.append(reaction)}if(message.meme){const disclosure=el('details','meme-disclosure');disclosure.append(el('summary','','See the meme ↗'),memeCard(message.meme,message,isDemo));item.append(disclosure)}if(message.memeError)item.append(el('p','meme-error','The check completed, but the extra meme could not be created. The evidence and correction are still here.'));if(!isDemo&&check?.status==='issue'&&check.issues?.length){const row=el('div','repair-row'),repaired=message.repaired||check.issues.every(i=>i.repaired);const repair=button(repaired?'✓ Restored for future replies':'Restore this context','repair-button',()=>mutate('repair',{messageId:message.id}));repair.dataset.mutation='true';repair.dataset.completed=String(Boolean(repaired));repair.disabled=busy||repaired;row.append(repair,el('span','',repaired?'The original will be included in future replies.':'Keep chatting. The original reply stays on record.'));item.append(row)}}return item}
function renderChat(){const chat=$('#chat'),shouldScroll=chat.scrollHeight-chat.clientHeight-chat.scrollTop<100;chat.replaceChildren();if(!(state.chat||[]).length){const welcome=el('div','welcome');const mark=el('span','welcome-cat');mark.append(catImage(CAT_IMAGES.calico),el('small','','no thoughts. just vibes.'));welcome.append(mark,el('h2','','BIG CHAT. ZERO CHILL.'),el('p','',chaosEnabled?'Chaos is ON. The first two replies stay normal. Every third reply takes a ridiculous detour with a reaction meme—then the cycle repeats. Real memory slips still get an immediate, separate alert with receipts.':'Chaos is OFF. Chat normally with evidence-backed memory checks. Turn it on for a ridiculous detour and reaction meme every third reply.'));const suggestions=el('div','suggestions');for(const text of ['I have 3 minutes to pitch my project. Help me plan it.','My project is Memory Glitch. My budget is 50 AUD. Remember both.'])suggestions.append(button(text,'',()=>{$('#message').value=text;$('#message').focus()}));welcome.append(suggestions);const tour=el('section','welcome-tour');tour.append(el('h3','','WANT TO TEST THE MEMORY DETECTOR?'),el('p','','Normal meme reactions are just jokes. Try a checked mistake or real context removal below.'));const actions=el('div','welcome-tour-actions');actions.append(button('Try a checked glitch ↗','primary-button',()=>showDialog('#demo-dialog')));const testLink=el('a','lab-link','Run the real memory test ↗');testLink.href='./tests.html';actions.append(testLink);tour.append(actions);welcome.append(tour);chat.append(welcome)}else for(const message of state.chat)chat.append(messageNode(message));if(pending){const item=el('article','message assistant pending');const meta=el('div','message-meta');meta.append(el('span','avatar','✳'),el('span','','MEMORY GLITCH'));const text=el('div','message-text');text.append(el('span','typing-dot'),el('span','typing-dot'),el('span','typing-dot'),document.createTextNode(' Replying, then checking the receipts'));item.append(meta,text);chat.append(item)}if(shouldScroll||pending)requestAnimationFrame(()=>{chat.scrollTop=chat.scrollHeight})}
function renderSources(){const sources=state.sources||[];$('#source-count').textContent=String(sources.length);const wrap=$('#sources');wrap.replaceChildren();if(!sources.length)wrap.append(el('p','source-empty','Your words will appear here.\nThe ghosts do the filing.'));else for(const source of [...sources].reverse().slice(0,4)){const b=button('','source-button',()=>openSources(source.id));b.append(el('small','',`${formatTime(source.time)||'This session'} · ORIGINAL`),el('p','',source.text));wrap.append(b)}$('#all-sources').disabled=!sources.length;const last=[...(state.chat||[])].reverse().find(m=>m.role!=='user'&&m.check)?.check;$('#audit-summary').textContent=last?last.status==='issue'?`${last.issues?.length||1} supported mismatch found. The reply includes its evidence and correction.`:last.status==='clear'?`Checked ${last.checkedSources??last.referenceCoverage?.checked??0} original messages. No supported mismatch found.`:last.status==='uncertain'?'Not enough evidence to decide. No memory alert.':'The check did not complete. No memory alert.':'Waiting for the first reply.'}
function render(){updateChaosControl();renderChat();renderSources();setBusy(busy)}
async function mutate(operation,data){if(busy)return;setBusy(true);try{await api(operation,data);render();if(operation==='repair')toast('The cited original will be included in future chat context.');if(operation==='feedback')toast('Feedback saved. You decide what is funny.')}catch(error){toast(error.message)}finally{setBusy(false)}}
async function sendMessage(event){event?.preventDefault();if(busy)return;const input=$('#message'),message=input.value.trim();if(!message){input.focus();return}if(!configured){toast('AI is not connected yet. Please try again shortly.');return}pending=true;setBusy(true);renderChat();try{await api('chat',{message,chaos:chaosEnabled});if(input.value.trim()===message)input.value='';pending=false;render();const latest=[...(state.chat||[])].reverse().find(m=>m.role==='assistant');if(latest){celebrateIncident(latest);celebrateReaction(latest)}requestAnimationFrame(()=>{const chat=$('#chat');const item=latest&&[...chat.querySelectorAll('[data-message-id]')].find(n=>n.dataset.messageId===latest.id);const reaction=item?.querySelector('.haunt-card,.chat-reaction');if(reaction)chat.scrollTop+=reaction.getBoundingClientRect().top-chat.getBoundingClientRect().top-10;else chat.scrollTop=chat.scrollHeight})}catch(error){pending=false;render();toast(error.message)}finally{setBusy(false);input.focus()}}
async function runDemo(){if(busy)return;setBusy(true,'Running the live demo check…');const target=$('#demo-content');target.replaceChildren(el('p','dialog-note','Checking the scripted reply against the original message…'));try{const result=await api('demo',{caseId:$('#demo-case').value});demoResult=result.demo;target.replaceChildren();for(const message of demoResult?.messages||[])target.append(messageNode(message,true));if(!(demoResult?.messages||[]).length)target.append(el('p','dialog-note','No demo result was returned. Please try again.'));else{if((demoResult.messages||[]).some(m=>m.check?.status==='clear'))target.append(el('p','demo-success','All quiet. A correct reply does not trigger a ghost.'));target.append(button('Continue chatting →','continue-chat',()=>{$('#demo-dialog').close();$('#message').focus()}));for(const message of demoResult.messages)celebrateIncident(message,true)}renderSources()}catch(error){target.replaceChildren(el('p','dialog-note',error.message));toast(error.message)}finally{setBusy(false)}}
function exportData(){$('#menu-dialog').close();const content=JSON.stringify({exportedAt:new Date().toISOString(),product:'Memory Glitch',notice:'Original messages are evidence of user statements, not external verification. Memes and character remarks are fictional comedy.',state},null,2);$('#export-json').value=content;showDialog('#export-dialog');const url=URL.createObjectURL(new Blob([content],{type:'application/json'}));const a=el('a');a.href=url;a.download=`memory-glitch-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000)}
$('#chat-form').addEventListener('submit',sendMessage);$('#message').addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendMessage()}});$('#help').addEventListener('click',()=>showDialog('#help-dialog'));$('#menu-open').addEventListener('click',()=>showDialog('#menu-dialog'));$('#menu-help').addEventListener('click',()=>{$('#menu-dialog').close();showDialog('#help-dialog')});$('#all-sources').addEventListener('click',()=>openSources());$('#audit-open').addEventListener('click',openAudit);$('#demo-open').addEventListener('click',()=>showDialog('#demo-dialog'));$('#demo-run').addEventListener('click',runDemo);$('#tour-demo')?.addEventListener('click',()=>{$('#help-dialog').close();showDialog('#demo-dialog')});$('#demo-case').addEventListener('change',()=>{$('#demo-content').replaceChildren();demoResult=null});$('#export').addEventListener('click',exportData);$('#export-copy').addEventListener('click',()=>{$('#export-json').focus();$('#export-json').select()});document.querySelectorAll('[data-close]').forEach(n=>n.addEventListener('click',()=>n.closest('dialog').close()));for(const target of document.querySelectorAll('[data-character]'))target.append(characterArt(target.dataset.character));
$('#chaos-toggle').addEventListener('click',()=>{if(busy)return;chaosEnabled=!chaosEnabled;try{localStorage.setItem(CHAOS_KEY,chaosEnabled?'on':'off')}catch{}updateChaosControl();if(!(state.chat||[]).length)renderChat();toast(chaosEnabled?'Chaos on: two normal replies, then one playful burst. Real memory alerts stay immediate.':'Chaos off. Plain replies; real memory alerts stay on.');$('#message').focus()});
updateChaosControl();render();load();
